(* [comment removed for export] *)
Definition rs_frame (m : mem) (sp : word) (j8 : list byte) (t1c t2c : list cell) : Prop :=
  rw_cells usegs m (bv_unsigned sp + -128) [CB 8 j8]
  /\ rw_cells usegs m (bv_unsigned sp + -120) t1c /\ cells_size t1c = 24%nat
  /\ rw_cells usegs m (bv_unsigned sp + -96) t2c /\ cells_size t2c = 24%nat.

