    (F : bvmap 5 word) fc (m : mem) (lo P : Z) (FB : fbv) (ej : list byte),
  rw_cells usegs m (P + O_H_FB) (FlatBufCells FB) ->
  rw_cells usegs m (P + O_H_EC) [CB 24 ej] ->
  stk usegs m lo (bv_unsigned sp) -> lo + 128 <= bv_unsigned sp -> 0xb8000 <= lo ->
  bv_unsigned sp <= P -> P + 488 <= 2^64 ->
  0 <= fb_in FB -> fb_in FB <= fb_out FB -> fb_out FB < 2^64 ->
  mem_inv usegs m ->
  evt usegs (fun ms' => exists m' j8 jt1 t2c,
           munch [(lo, bv_unsigned sp); (P + O_H_EC, P + O_H_EC + 24)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
