Definition rs_retd_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (lo tot : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6,
      ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz tot) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
               F (ret_pc ra) fc None m (seg_rom usegs)
      /\ stk usegs m lo (bv_unsigned sp).

Definition rs_ret_stmt : Prop :=
  forall rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s1x s2x s3x s4x s5x s6x s7x s8 s9 s10 s11 s0v s1v s2v s3v s4v s5v s6v s7v t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (lo tot : Z) (j8 : list byte) (t1c t2c : list cell),
  rs_frame m sp j8 t1c t2c ->
  rw_cells usegs m (bv_unsigned sp + -72) (map C8 (rs_sv s7v s6v s5v s4v s3v s2v s1v s0v ra)) ->
  stk usegs m lo (bv_unsigned sp + -128) -> 0 <= lo -> lo <= bv_unsigned sp + -128 -> 0 <= tot < 2^64 ->
  evt usegs (rs_retd_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8 s9 s10 s11 F fc lo tot m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -128)) gp tp t0 t1 t2 (wz tot) s1x a0 a1 a2 a3 a4 a5 a6 a7
             s2x s3x s4x s5x s6x s7x s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 RS_RET) fc None m (seg_rom usegs)).

