(* [comment removed for export] *)
Definition rs_W2 (lo : Z) (sp : word) (P : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp + -72); (P + O_H_FB, P + O_H_FB + 24); (G_HTTP_CAT, G_HTTP_CAT + 64)]%Z.

(* [comment removed for export] *)
Definition rs_eqnm_post (ra sp gp tp s5x s6x s7x s8 s9 s10 s11 s0v s1v s2v s3v s4v s5v s6v s7v : word)
    (F : bvmap 5 word) (fc : bv 32) (m : mem) (lo P tot : Z) (FBC : list cell) (E1 : ecv) : machine_state -> Prop :=
