Definition rs_after_put_stmt : Prop :=
  forall rax ra sp gp tp t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 s5x s6x s7x s8 s9 s10 s11 s0v s1v s2v s3v s4v s5v s6v s7v t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (lo P tot used : Z) (FB : fbv) (E1 : ecv) (g : bool) (j8 : list byte) (t1c t2c : list cell),
  rs_frame m sp j8 t1c t2c ->
  rw_cells usegs m (bv_unsigned sp + -72) (map C8 (rs_sv s7v s6v s5v s4v s3v s2v s1v s0v ra)) ->
  rw_cells usegs m (P + O_H_FB) (FlatBufCells FB) ->
  rw_cells usegs m (P + O_H_EC) (ErrCodeCells E1) -> ec_ok E1 -> (E1 = EC_clear \/ http_fail E1) ->
  HttpCat m g -> XStatics m ->
  stk usegs m lo (bv_unsigned sp + -128) -> lo + 160 <= bv_unsigned sp -> 0xb8000 <= lo ->
  bv_unsigned sp <= P -> P + 488 <= 2^64 ->
  0 <= fb_begin FB -> fb_begin FB <= fb_in FB -> fb_in FB <= fb_out FB -> fb_out FB < 2^64 -> 0 <= used <= fb_size FB ->
  0 <= tot -> tot + used < 2^64 ->
  (0 < fb_size FB -> 0 < fb_in FB) ->                          (* [comment removed for export] *)
  mem_inv usegs m ->
  evt usegs (fun ms' => exists m',
          munch (rs_W2 lo sp P) m m' /\ wmono usegs m m' /\ mem_inv usegs m'
       /\ rw_cells usegs m' (P + O_H_FB) (FlatBufCells (fb_consume FB used))
       /\ rw_cells usegs m' (P + O_H_EC) (ErrCodeCells E1)
       /\ HttpCat m' true /\ XStatics m'
       /\ (   (is_needmore E1 = false /\ rs_retd_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8 s9 s10 s11 F fc lo (tot + used) m' ms')
           \/ (is_needmore E1 = true /\ exists j8' jt1 jt2 rax' t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6',
                 stk usegs m' lo (bv_unsigned sp + -128)
                 /\ rs_frame m' sp j8' [CB 24 jt1] [CB 24 jt2]
                 /\ rw_cells usegs m' (bv_unsigned sp + -72) (map C8 (rs_sv s7v s6v s5v s4v s3v s2v s1v s0v ra))
                 /\ ms' = rs_ms RS_DOREAD rax' sp gp tp t0' t1' t2' (tot + used) P a0' a1' a2' a3' a4' a5' a6' a7' (wz used) s6x s7x s8 s9 s10 s11 t3' t4' t5' t6' F fc m')))
    (rs_ms RS_PUTRET rax sp gp tp t0 t1 t2 tot P (wz used) a1 a2 a3 a4 a5 a6 a7 s5x s6x s7x s8 s9 s10 s11 t3 t4 t5 t6 F fc m).

