Definition rs_doread1_stmt : Prop :=
  forall rax sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s5x s6x s7x s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P tot : Z) (LB : list block) (FB : fbv) (ds : list byte),
  FlatBuf LB m (P + O_H_FB) FB ds -> P mod 8 = 0 -> 0 <= P -> P + 488 <= 2^64 -> 0 <= bv_unsigned sp ->
  mem_inv usegs m ->
  evt usegs (fun ms' => exists a5' t0' t1' t2' t3' t4' t5' t6',
        ms' = MS (mkR (wz RS_DBPRET) (Z_to_bv 64 (bv_unsigned sp + -128)) gp tp t0' t1' t2' (wz tot) (wz (P + O_H_EC))
                      (Z_to_bv 64 (bv_unsigned sp + -96)) (wz (P + O_H_FB)) (wz (read_size_val FB)) (wz (P + O_H_EC)) (wz 7) a5' a6 a7
                      (wz P) (wz (P + O_H_FB)) (wz (P + O_H_STREAM)) s5x s6x s7x s8 s9 s10 s11 t3' t4' t5' t6')
                 F (Z_to_bv 64 P_FB_DYN_PREPARE) fc None m (seg_rom usegs)
        /\ munch [] m m /\ wmono usegs m m /\ mem_inv usegs m)
    (rs_ms RS_DOREAD rax sp gp tp t0 t1 t2 tot P a0 a1 a2 a3 a4 a5 a6 a7 s5x s6x s7x s8 s9 s10 s11 t3 t4 t5 t6 F fc m).

